html, body, #root { background: #000; }
.track {
  position: absolute;
  left: 70px;
  right: 70px;
  top: 50%;
  transform: translateY(-50%);
  display: flex;
  justify-content: center;
  gap: 34px;
  perspective: 900px;
}
.word-mask {
  position: relative;
  width: 236px;
  height: 340px;
  overflow: hidden;
}
.word-mask.wide { width: 454px; }
.word {
  position: absolute;
  left: 0;
  top: 82px;
  color: #fff;
  font-size: 116px;
  line-height: 1;
  font-weight: 760;
  letter-spacing: 0;
  white-space: nowrap;
  transform-origin: 50% 100%;
}
